node -e '
const { deliver } = require("/workspace/src/dispatcher.js");

(async () => {
  // 1. Success on first attempt -> exactly 1 post, no sleep
  let posts = 0, sleeps = [];
  const io1 = { post: async () => { posts++; return { status: 200 }; }, sleep: async (ms) => sleeps.push(ms) };
  let res = await deliver(io1, { id: "evt_1", type: "charge" });
  console.log("1) first-attempt success:", JSON.stringify(res), "posts=" + posts, "sleeps=" + JSON.stringify(sleeps));

  // 2. Intermittent 502s then success -> retries with backoff, returns 200
  posts = 0; sleeps = [];
  const io2 = { post: async (path, body, opts) => {
    posts++;
    console.log("   post#"+posts, "path="+path, "idempotency-header="+(opts && opts.headers && opts.headers["Idempotency-Key"]));
    return posts < 3 ? { status: 502 } : { status: 200 };
  }, sleep: async (ms) => sleeps.push(ms) };
  res = await deliver(io2, { id: "evt_2" });
  console.log("2) retry-then-success:", JSON.stringify(res), "posts="+posts, "sleeps="+JSON.stringify(sleeps));

  // 3. Persistent 5xx -> bounded to maxAttempts, returns last response, no sleep after final
  posts = 0; sleeps = [];
  const io3 = { post: async () => { posts++; return { status: 503 }; }, sleep: async (ms) => sleeps.push(ms) };
  res = await deliver(io3, { id: "evt_3" });
  console.log("3) persistent-503:", JSON.stringify(res), "posts="+posts, "sleeps="+JSON.stringify(sleeps));

  // 4. Event without id -> still retries, no header
  posts = 0; sleeps = [];
  const io4 = { post: async (path, body, opts) => {
    posts++;
    console.log("   post#"+posts, "opts="+JSON.stringify(opts));
    return posts < 2 ? { status: 502 } : { status: 204 };
  }, sleep: async (ms) => sleeps.push(ms) };
  res = await deliver(io4, { type: "charge" });
  console.log("4) no-id event:", JSON.stringify(res), "posts="+posts);
})();
'

